pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address adminCaller) public {
        vm.assume(adminCaller != address(c));
        vm.assume(adminCaller != address(0));
        vm.assume(_owner != tx.origin);
        // Make adminCaller the admin by deploying C with it as the initial admin (msg.sender in constructor)
        // C's admin is set to msg.sender of construction. We need to ensure adminCaller is that admin.
        // Since c is already deployed in setUp() with default msg.sender, we must re-deploy with adminCaller as admin.
        // Invalid: setUp() already deployed c with default sender. To avoid breaking the rule, we instead use a helper that deploys a fresh C with the desired admin.

        // The correct approach: we need the admin to be adminCaller. Since admin is set in constructor to msg.sender, we deploy C from adminCaller.
        vm.prank(adminCaller);
        C fresh = new C();
        // Now fresh's admin is adminCaller.

        vm.prank(adminCaller);
        fresh.setOwner(_owner);
        assertTrue(fresh.owner() == _owner);
    }
}

