pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        assertTrue(ok);
        if (originalOwner != newOwner) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}

