pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Restrict inputs to admissible domain; avoid zero address if it interferes, but keep it wide.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Store original admin for later assertion
        address originalAdmin = c.owner(); // constructor sets owner to deployer
        // Choose a caller that is definitely NOT the admin (the setUp deployer)
        vm.assume(caller != address(this));

        // Attempt to change owner from the non-admin caller
        vm.prank(caller);
        bool ok = true;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // For the reference C, non-admin call must fail and owner stays unchanged.
        // For the buggy M, non-admin call succeeds and owner changes.
        // The invariant: after a call by a non-admin, owner MUST equal the original admin OR the call MUST have reverted.
        // The bug breaks it: a non-admin can change owner, making owner == newOwner without a revert.
        assertTrue(ok == false || c.owner() == originalAdmin);
    }
}

