pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address nextOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(nextOwner != address(0));
        vm.assume(newOwner != nextOwner);
        // Let the original admin (this test contract) call setOwner to set newOwner
        c.setOwner(newOwner);
        // Now impersonate newOwner and try to change the owner again
        vm.prank(newOwner);
        bool ok;
        try c.setOwner(nextOwner) { ok = true; } catch { ok = false; }
        // In the reference C, only admin can call setOwner, so this call MUST revert (ok == false)
        assertTrue(!ok);
    }
}

