import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // The admin is msg.sender in setUp (this contract), so we can call setOwner directly.
        // No adversarial helper is needed; the difference is a pure return value accessible via the public surface.
        // We verify that when called by the admin, setOwner always returns true.
        vm.prank(address(this));
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        assertTrue(success);
        bool returnValue = abi.decode(ret, (bool));
        assertTrue(returnValue);
    }
}

