pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c)); // though harmless
        address initialOwner = c.owner();
        vm.prank(caller);
        bool ok = true;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        address finalOwner = c.owner();
        // In the reference contract, only the admin can change the owner.
        // Since the admin is the deployer (this test contract), and the caller is not the deployer,
        // the call must revert and the owner must stay unchanged.
        // The bug makes onlyAdmin() accept any sender, so the call succeeds and the owner changes.
        assertTrue(!ok || finalOwner == initialOwner);
    }
}
